CREATE TABLE IF NOT EXISTS families(id text PRIMARY KEY,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS media(id text PRIMARY KEY,mime text NOT NULL,data bytea NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS people(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families ON DELETE CASCADE,name text NOT NULL,age numeric NOT NULL,gender text NOT NULL,photo_id text REFERENCES media,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS relations(id text PRIMARY KEY,source_id text NOT NULL REFERENCES people ON DELETE CASCADE,target_id text NOT NULL REFERENCES people ON DELETE CASCADE,role text NOT NULL,CHECK(source_id<>target_id),UNIQUE(source_id,target_id,role));
CREATE TABLE IF NOT EXISTS memories(id text PRIMARY KEY,person_id text NOT NULL REFERENCES people ON DELETE CASCADE,text text NOT NULL,original_text text NOT NULL,original_event_date date NOT NULL,event_date date NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS books(id text PRIMARY KEY,family_id text NOT NULL REFERENCES families,person_id text REFERENCES people ON DELETE SET NULL,page_count integer NOT NULL CHECK(page_count BETWEEN 1 AND 20),prompt text NOT NULL,snapshot jsonb NOT NULL,status text NOT NULL DEFAULT 'queued',title text NOT NULL DEFAULT 'Din bok skapas',story jsonb,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),request_key text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS pages(book_id text NOT NULL REFERENCES books ON DELETE CASCADE,number integer NOT NULL,text text NOT NULL,image_id text NOT NULL REFERENCES media,PRIMARY KEY(book_id,number));
CREATE TABLE IF NOT EXISTS budget(id integer PRIMARY KEY CHECK(id=1),limit_ore bigint NOT NULL CHECK(limit_ore BETWEEN 0 AND 50000),committed_ore bigint NOT NULL DEFAULT 0 CHECK(committed_ore>=0),storage_bytes bigint NOT NULL DEFAULT 0);
INSERT INTO budget(id,limit_ore) VALUES(1,50000) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS charges(id text PRIMARY KEY,book_id text NOT NULL REFERENCES books,kind text NOT NULL,reserved_ore bigint NOT NULL,actual_ore bigint,state text NOT NULL DEFAULT 'reserved',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(book_id,kind));

ALTER TABLE memories ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'event';
CREATE UNIQUE INDEX IF NOT EXISTS one_profile_per_person ON memories(person_id) WHERE kind='profile';
ALTER TABLE charges ALTER COLUMN book_id DROP NOT NULL;
ALTER TABLE charges DROP CONSTRAINT IF EXISTS charges_book_id_fkey;
ALTER TABLE charges ADD CONSTRAINT charges_book_id_fkey FOREIGN KEY(book_id) REFERENCES books(id) ON DELETE SET NULL;
ALTER TABLE families ADD COLUMN IF NOT EXISTS pin_hash text;
ALTER TABLE families ADD COLUMN IF NOT EXISTS pin_setup_hash text;
ALTER TABLE families ADD COLUMN IF NOT EXISTS pin_failures integer NOT NULL DEFAULT 0;
ALTER TABLE families ADD COLUMN IF NOT EXISTS pin_locked_until timestamptz;
CREATE TABLE IF NOT EXISTS family_sessions(token_hash text PRIMARY KEY,family_id text NOT NULL REFERENCES families ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS family_sessions_expiry ON family_sessions(expires_at);
